export const METHOD='bm25-concepts-v1';
const stop=new Set('a an the and or for to of in on with is are be that this from we need want help our can without using develop solution'.split(' '));
const concepts=[['water','purification','purify','filtration','filter','contaminants','contamination','wastewater','clean'],['thermal','heat','cooling','cool','temperature','dissipation'],['energy','power','electricity','renewable','solar'],['battery','batteries','storage'],['agriculture','crop','crops','soil','irrigation','farming'],['sensor','sensors','sensing','monitor','monitoring','detect','detection'],['manufacturing','fabrication','printing','manufacture']];
export function tokens(text){return String(text).toLowerCase().match(/[a-z0-9]+/g)?.filter(w=>w.length>1&&!stop.has(w))||[];}
export function rank(records,query){const original=[...new Set(tokens(query))];if(!original.length)return records.map(record=>({record,score:0,matched:[],expanded:[]}));const expansion=[...new Set(concepts.filter(g=>g.some(w=>original.includes(w))).flat())].filter(w=>!original.includes(w));const docs=records.map(r=>tokens(r.title+' '+r.title+' '+r.description+' '+r.category));const avg=docs.reduce((s,d)=>s+d.length,0)/Math.max(docs.length,1);const df=new Map([...original,...expansion].map(t=>[t,docs.filter(d=>d.includes(t)).length]));return records.map((record,i)=>{let score=0;for(const t of [...original,...expansion]){const count=docs[i].filter(w=>w===t).length;const idf=Math.log(1+(records.length-df.get(t)+.5)/(df.get(t)+.5));score+=(original.includes(t)?1:.22)*idf*(count*2.2)/(count+1.2*(.25+.75*docs[i].length/(avg||1)));}return {record,score,matched:original.filter(t=>docs[i].includes(t)),expanded:expansion.filter(t=>docs[i].includes(t))};}).filter(r=>r.score>0).sort((a,b)=>b.score-a.score||a.record.id.localeCompare(b.record.id));}
export function requirements(text){return text.split(/\n|;/).map(s=>s.trim()).filter(Boolean).slice(0,20);}
export function brief(records,problem,constraints,notes={}){return '# Patent2Market investigation brief\n\nProblem: '+(problem||'Exploratory discovery')+'\n\nMethod: '+METHOD+'; lexical retrieval with curated concept expansion. Scores are retrieval relevance, not feasibility.\n\n## Requirements to verify\n'+requirements(constraints).map(r=>'- [ ] '+r).join('\n')+'\n\n'+records.map(r=>'## '+r.title+'\n\n'+r.description+'\n\nSource: '+r.url+'\nRetrieved: '+r.retrievedAt+'\n\nRights: '+r.rights+'\n\nTRL, cost, technical constraint satisfaction: not assessed.\n\nInvestigation notes: '+(notes[r.id]||'None yet')+'\n\nNext: verify operating conditions, performance evidence, implementation needs, and licensing with the source.').join('\n\n');}
